namespace Rag.Application.Models;

/// <summary>
/// Represents the answer generated by the RAG application.
/// </summary>
public class RagAnswerResponse
{
    /// <summary>
    /// Gets or sets the generated answer.
    /// </summary>
    public string Answer { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the document chunks used to generate the answer.
    /// </summary>
    public List<RetrievedChunk> Sources { get; set; } = [];
}